use std::sync::mpsc::{sync_channel, TryRecvError};

let (tx, rx) = sync_channel::<Event>(256);   // bounded: send blocks when full
tx.send(Event::Sound { id: SoundId::Bloop, volume: 0.8 }).unwrap();

loop {
    match rx.try_recv() {
        Ok(ev) => handle(ev),                 // drain one per tick
        Err(TryRecvError::Empty | TryRecvError::Disconnected) => break,
    }
}
